# Check K_{6,6} is triangle-free and maximal
n = 12
left = list(range(0,6))
right = list(range(6,12))

edges = []
for u in left:
    for v in right:
        edges.append((u,v))

# Check triangle-free
adj = [[False]*n for _ in range(n)]
for u,v in edges:
    adj[u][v] = adj[v][u] = True

def has_triangle():
    for i in range(n):
        for j in range(i+1, n):
            if adj[i][j]:
                for k in range(j+1, n):
                    if adj[i][k] and adj[j][k]:
                        return True
    return False

print("Has triangle:", has_triangle())

# Check maximal: adding any missing edge creates triangle
def is_maximal():
    for i in range(n):
        for j in range(i+1, n):
            if not adj[i][j]:
                # add edge
                adj[i][j] = adj[j][i] = True
                # check if triangle created
                tri = False
                for k in range(n):
                    if k != i and k != j and adj[i][k] and adj[j][k]:
                        tri = True
                        break
                if not tri:
                    # adding edge didn't create triangle
                    adj[i][j] = adj[j][i] = False
                    return False, (i,j)
                adj[i][j] = adj[j][i] = False
    return True, None

maximal, edge = is_maximal()
print("Is maximal:", maximal)
if not maximal:
    print("Counterexample edge:", edge)
